SELECT	att04_commute_hist_id
  FROM 	att04_commute_hist
 WHERE	att04_commute_id = #{commuteId}

mapper.update:
UPDATE	att04_commute_hist
   SET	att04_reg_person_id = #{personId}
     ,	att04_change_reason = #{changeReason}
     ,	att04_reg_date = f_sysdate()


	 ,	att04_after_in = TO_TIMESTAMP(TO_CHAR(#{checkInTime}::date,'YYYY-MM-DD')||' '||#{checkInTimeStr},'YYYY-MM-DD HH24:MI:SS')


 	,	att04_after_out = TO_TIMESTAMP(TO_CHAR(#{checkOutTime}::date,'YYYY-MM-DD')||' '||#{checkOutTimeStr},'YYYY-MM-DD HH24:MI:SS')


 WHERE	att04_commute_id = #{commuteId}
